(() => {
  "use strict";
  const root = document.querySelector("[data-panel-app]");
  const tokenKey = "prisma-panel-session";
  const api = async (path, options = {}) => {
    const token = sessionStorage.getItem(tokenKey);
    const response = await fetch(path, {headers: {"Content-Type": "application/json", ...(token ? {Authorization: `Bearer ${token}`} : {}), ...(options.headers || {})}, ...options});
    const data = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(data.error || "Não foi possível concluir a operação.");
    return data;
  };
  const esc = (value = "") => String(value).replace(/[&<>"']/g, (char) => ({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#039;"}[char]));
  const shell = (content) => `<div class="panel-shell"><aside class="panel-sidebar"><a class="brand panel-brand" href="/"><svg class="brand-mark" viewBox="0 0 40 40"><path class="brand-mark-outline" d="M20 3 36.5 32H3.5L20 3Z"/><path class="brand-mark-face" d="M20 3v29H3.5L20 3Z"/><path class="brand-mark-ray" d="M21 19.5h17"/></svg><span class="brand-word">PRISMA</span><span class="panel-brand-label">Editorial</span></a><p class="panel-sidebar__eyebrow">Gestão de conteúdo</p><nav class="panel-nav"><a href="/painel/" aria-current="page"><span class="panel-nav__icon"><i></i><i></i><i></i></span><span><strong>Cases</strong><small>Portfólio das frentes</small></span></a><a href="/" target="_blank"><span class="panel-nav__icon panel-nav__icon--arrow">↗</span><span><strong>Ver site</strong><small>Abrir uma nova aba</small></span></a></nav><div class="panel-sidebar__bottom"><div class="panel-theme"><p>Versão visual</p><div class="theme-switcher"><button class="theme-choice" data-theme-choice="golden" title="Golden">Golden</button><button class="theme-choice" data-theme-choice="solar" title="Solar">Solar</button></div></div><div class="panel-user"><span class="panel-user__avatar">P</span><span class="panel-user__identity"><strong>Equipe Prisma</strong><small>Acesso editorial</small></span><button class="panel-logout" type="button" data-logout title="Sair">↪</button></div></div></aside><div class="panel-main"><header class="panel-mobile-header"><a class="brand" href="/"><span class="brand-word">PRISMA</span></a><button class="panel-menu-toggle" type="button" data-panel-menu-toggle aria-expanded="false"><span class="visually-hidden">Abrir menu do painel</span><span></span><span></span></button></header>${content}</div></div><div class="panel-overlay" data-panel-overlay></div>`;
  const caseForm = (item = {}) => `<main class="panel-page"><header class="panel-page-header panel-editor-header"><div><a class="panel-back-link" href="/painel/">← Voltar para cases</a><p class="panel-kicker">${item.slug ? "Editar case" : "Novo case"}</p><h1>${item.slug ? "Ajustar o case." : "Criar um case."}</h1><p>Associe o trabalho à frente principal e publique apenas informações autorizadas.</p></div></header><form data-case-form><div class="panel-editor"><div><section class="panel-form-section"><header class="panel-form-section__header"><span>01</span><div><h2>Posicionamento</h2><p>O que vai aparecer na listagem de cases.</p></div></header><div class="panel-form-grid"><div class="panel-field"><label for="id_front">Frente <span>*</span></label><select class="panel-control panel-select" id="id_front" name="front" required><option value="">Selecione</option><option value="marketing" ${item.front === "marketing" ? "selected" : ""}>Marketing</option><option value="tecnologia" ${item.front === "tecnologia" ? "selected" : ""}>Tecnologia</option></select></div><div class="panel-field"><label for="id_status">Status <span>*</span></label><select class="panel-control panel-select" id="id_status" name="status"><option value="draft" ${item.status !== "published" ? "selected" : ""}>Rascunho</option><option value="published" ${item.status === "published" ? "selected" : ""}>Publicado</option></select></div><div class="panel-field panel-field--full"><div class="panel-field__label-row"><label for="id_title">Título <span>*</span></label><span data-count-for="id_title">0 / 120</span></div><input class="panel-control" id="id_title" name="title" maxlength="120" required value="${esc(item.title)}"></div><div class="panel-field"><label for="id_category">Categoria <span>*</span></label><input class="panel-control" id="id_category" name="category" maxlength="80" required value="${esc(item.category)}" placeholder="Ex.: Plataforma digital"></div><div class="panel-field"><label for="id_deliverables">Entregáveis <span>*</span></label><input class="panel-control" id="id_deliverables" name="deliverables" maxlength="220" required value="${esc(item.deliverables)}" placeholder="Ex.: Estratégia, UX/UI, desenvolvimento"></div><div class="panel-field panel-field--full"><div class="panel-field__label-row"><label for="id_summary">Resumo <span>*</span></label><span data-count-for="id_summary">0 / 240</span></div><textarea class="panel-control" id="id_summary" name="summary" maxlength="240" required>${esc(item.summary)}</textarea></div></div></section><section class="panel-form-section"><header class="panel-form-section__header"><span>02</span><div><h2>História do projeto</h2><p>Contexto que aparece na página individual do case.</p></div></header><div class="panel-form-grid panel-form-grid--narrative"><div class="panel-field"><label for="id_challenge">O desafio <span>*</span></label><textarea class="panel-control" id="id_challenge" name="challenge" required>${esc(item.challenge)}</textarea></div><div class="panel-field"><label for="id_solution">A solução <span>*</span></label><textarea class="panel-control" id="id_solution" name="solution" required>${esc(item.solution)}</textarea></div><div class="panel-field panel-field--full"><label for="id_external_url">Link externo <span class="optional">opcional</span></label><input class="panel-control" id="id_external_url" name="external_url" type="url" value="${esc(item.external_url)}" placeholder="https://"></div><label class="panel-checkbox-field panel-field--full"><input class="panel-checkbox" name="featured" type="checkbox" ${item.featured ? "checked" : ""}><span><strong>Destacar no portfólio</strong><span>O case recebe maior evidência na grade.</span></span></label></div></section><p class="panel-form-alert" hidden data-form-error></p><div class="panel-form-actions"><a class="panel-cancel" href="/painel/">Cancelar</a><button class="button" type="submit">${item.slug ? "Salvar alterações" : "Criar case"} <span>↗</span></button></div></div><aside class="panel-editor__summary"><div class="panel-editor-summary-card"><div class="panel-editor-summary-card__art"><span></span></div><span class="panel-summary-front" data-summary-front>Frente do case</span><h2 data-summary-title>Case sem título</h2><dl><div><dt>Status</dt><dd data-summary-status>Rascunho</dd></div><div><dt>Publicação</dt><dd>Após salvar</dd></div></dl><p class="panel-editor-summary-card__note">Imagens podem ser hospedadas no Cloudflare R2 em uma próxima etapa. Este case usa a composição visual da Prisma.</p></div></aside></div></form></main>`;
  function bindPanelControls() {
    document.querySelector("[data-logout]")?.addEventListener("click", () => { sessionStorage.removeItem(tokenKey); renderLogin(); });
    document.querySelectorAll("[data-theme-choice]").forEach((button) => button.addEventListener("click", () => {
      const theme = button.dataset.themeChoice;
      document.documentElement.dataset.theme = theme;
      document.querySelectorAll("[data-theme-choice]").forEach((choice) => choice.setAttribute("aria-pressed", String(choice === button)));
      try { localStorage.setItem("prisma-theme", theme); } catch (_) { /* preferência opcional */ }
    }));
    const menu = document.querySelector("[data-panel-menu-toggle]"); const overlay = document.querySelector("[data-panel-overlay]");
    menu?.addEventListener("click", () => document.body.classList.toggle("panel-menu-open")); overlay?.addEventListener("click", () => document.body.classList.remove("panel-menu-open"));
  }
  async function renderDashboard() {
    try {
      const {cases} = await api("/api/cases");
      const cards = cases.length ? cases.map((item) => `<article class="panel-project"><div class="panel-project__visual"><div class="panel-project__art"><span></span></div></div><div class="panel-project__body"><div class="panel-project__badges"><span class="panel-badge">${item.front === "marketing" ? "Marketing" : "Tecnologia"}</span><span class="panel-badge panel-badge--${item.status}"><i></i>${item.status === "published" ? "Publicado" : "Rascunho"}</span></div><h3>${esc(item.title)}</h3><p>${esc(item.summary)}</p><div class="panel-project__meta"><span>${esc(item.category)}</span><span>${item.featured ? "Em destaque" : ""}</span></div></div><div class="panel-project__actions"><button class="panel-action panel-action--primary" data-edit="${esc(item.slug)}">Editar →</button><a class="panel-action" href="/case.html?slug=${encodeURIComponent(item.slug)}" target="_blank">Ver página ↗</a></div></article>`).join("") : `<div class="panel-empty-state"><div class="panel-empty-state__art"><span></span></div><p class="panel-kicker">Portfólio vazio</p><h3>O próximo case começa aqui.</h3><p>Registre um trabalho real, vincule-o à frente correta e publique quando estiver autorizado.</p></div>`;
      const published = cases.filter((item) => item.status === "published").length;
      root.innerHTML = shell(`<main class="panel-page"><header class="panel-page-header"><div><p class="panel-kicker">Painel editorial</p><h1>Cases em movimento.</h1><p>Administre os trabalhos de Marketing e Tecnologia sem depender do Django Admin.</p></div><button class="button" data-new-case>Novo case <span>↗</span></button></header><section class="panel-metrics"><article class="panel-metric panel-metric--total"><span class="panel-metric__label">Todos os cases</span><strong>${cases.length}</strong><span class="panel-metric__detail">Portfólio Prisma</span></article><article class="panel-metric"><span class="panel-metric__label">Publicados</span><strong>${published}</strong><span class="panel-metric__mark"></span></article><article class="panel-metric panel-metric--draft"><span class="panel-metric__label">Rascunhos</span><strong>${cases.length - published}</strong><span class="panel-metric__mark"></span></article><article class="panel-metric panel-metric--marketing"><span class="panel-metric__label">Marketing</span><strong>${cases.filter((item) => item.front === "marketing").length}</strong><span class="panel-metric__index">01</span></article><article class="panel-metric panel-metric--tecnologia"><span class="panel-metric__label">Tecnologia</span><strong>${cases.filter((item) => item.front === "tecnologia").length}</strong><span class="panel-metric__index">02</span></article></section><section class="panel-collection"><header class="panel-collection__heading"><div><p class="panel-kicker">Biblioteca</p><h2>Cases cadastrados</h2></div><p>${cases.length} item(ns) nesta versão.</p></header><div class="panel-project-list">${cards}</div></section></main>`);
      bindPanelControls(); document.querySelector("[data-new-case]")?.addEventListener("click", () => renderForm()); document.querySelectorAll("[data-edit]").forEach((button) => button.addEventListener("click", () => renderForm(cases.find((item) => item.slug === button.dataset.edit))));
    } catch (error) { sessionStorage.removeItem(tokenKey); renderLogin(error.message); }
  }
  function renderForm(item) {
    root.innerHTML = shell(caseForm(item)); bindPanelControls();
    const form = document.querySelector("[data-case-form]");
    const sync = () => { document.querySelector("[data-summary-title]").textContent = form.title.value.trim() || "Case sem título"; document.querySelector("[data-summary-front]").textContent = form.front.selectedOptions[0]?.text || "Frente do case"; document.querySelector("[data-summary-status]").textContent = form.status.selectedOptions[0]?.text || "Rascunho"; };
    form.addEventListener("input", sync); form.addEventListener("change", sync); sync();
    form.addEventListener("submit", async (event) => { event.preventDefault(); const error = form.querySelector("[data-form-error]"); const data = Object.fromEntries(new FormData(form)); data.featured = form.featured.checked; if (item?.slug) data.slug = item.slug; try { await api("/api/cases", {method: item?.slug ? "PUT" : "POST", body: JSON.stringify(data)}); renderDashboard(); } catch (reason) { error.textContent = reason.message; error.hidden = false; } });
  }
  function renderLogin(message = "") {
    root.innerHTML = `<main class="panel-login"><section class="panel-login__brand"><div class="panel-login__brand-inner"><a class="brand" href="/"><svg class="brand-mark" viewBox="0 0 40 40"><path class="brand-mark-outline" d="M20 3 36.5 32H3.5L20 3Z"/><path class="brand-mark-face" d="M20 3v29H3.5L20 3Z"/><path class="brand-mark-ray" d="M21 19.5h17"/></svg><span class="brand-word">PRISMA</span></a><div class="panel-login__statement"><p class="panel-kicker">Área editorial</p><h1>Ideias em <em>movimento.</em></h1><p>Um espaço de trabalho para registrar e publicar os cases das duas frentes principais da Prisma.</p></div><div class="panel-login__prism"></div></div></section><section class="panel-login__access"><div class="panel-login__toolbar"><a class="back-link" href="/">← Voltar para o site</a><div class="theme-switcher"><button class="theme-choice" data-theme-choice="golden">Golden</button><button class="theme-choice" data-theme-choice="solar">Solar</button></div></div><div class="panel-login__form-shell"><p class="panel-kicker">Acesso da equipe</p><h2>Entrar no painel.</h2><p class="panel-login__intro">Use a senha configurada nos segredos do Cloudflare.</p><form class="panel-login-form" data-login-form><div class="panel-field"><label for="password">Senha</label><input class="panel-control" id="password" name="password" type="password" required autocomplete="current-password"></div>${message ? `<p class="panel-form-alert">${esc(message)}</p>` : ""}<button class="button panel-login__submit" type="submit">Entrar <span>→</span></button></form><p class="panel-login__note">O acesso é protegido pela Function do Cloudflare e expira automaticamente.</p></div></section></main>`;
    document.querySelectorAll("[data-theme-choice]").forEach((button) => button.addEventListener("click", () => { document.documentElement.dataset.theme = button.dataset.themeChoice; try { localStorage.setItem("prisma-theme", button.dataset.themeChoice); } catch (_) {} }));
    document.querySelector("[data-login-form]").addEventListener("submit", async (event) => { event.preventDefault(); const form = event.currentTarget; try { const {token} = await fetch("/api/session", {method:"POST", headers:{"Content-Type":"application/json"}, body:JSON.stringify({password: form.password.value})}).then(async (response) => { const data = await response.json(); if (!response.ok) throw new Error(data.error || "Não foi possível entrar."); return data; }); sessionStorage.setItem(tokenKey, token); renderDashboard(); } catch (error) { renderLogin(error.message); } });
  }
  document.addEventListener("DOMContentLoaded", () => sessionStorage.getItem(tokenKey) ? renderDashboard() : renderLogin());
})();
